package dev.veltraph.client.combat.slayer.tara;
import dev.veltraph.client.config.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class TaraParentConfigTest {
    @Test void disabledDefaultsAreInertAndEnabledUnknownContractIsRejected(){var c=new MapConfigService();assertTrue(TaraConfig.validation(c).isEmpty());c.set(TaraConfig.TARA_USE_SOUL_WHIP,true);assertTrue(TaraConfig.validation(c).isPresent());assertThrows(IllegalArgumentException.class,()->TaraConfig.profiles(c));}
    @Test void allProfileFieldsParticipateInFreezeSignature(){var c=new MapConfigService();var before=TaraConfig.signature(c);for(var key:PersistableKeys.collect(java.util.List.of(TaraConfig.class))){var changed=new MapConfigService();setChanged(changed,key);assertNotEquals(before,TaraConfig.signature(changed),key.name());}}
    @SuppressWarnings({"rawtypes","unchecked"}) private void setChanged(ConfigService c,ConfigKey key){Object v=key.defaultValue();c.set(key,v instanceof String?"declared":v instanceof Boolean?true:v instanceof Integer?3:v instanceof Long?1000L:1.0);}
    @Test void phaseBoundsAreDistinctAndOutcomeMustBeExplicit(){var c=declared();var p=TaraConfig.profiles(c);assertEquals(3,p.waiting().preparationTicks());assertEquals(5,p.eggs().bowPreparationTicks());assertEquals("minecraft:bow",p.eggs().bow().itemId());assertEquals(p.waiting().primary(),p.eggs().primary());c.set(TaraConfig.TARA_BOW_PREPARATION_TICKS,4);assertTrue(TaraConfig.validation(c).isPresent());c.set(TaraConfig.TARA_BOW_PREPARATION_TICKS,5);c.set(TaraConfig.TARA_EGG_OUTCOME,"");assertTrue(TaraConfig.validation(c).isPresent());}
    @Test void uuidReceiptAndNativeHealthDeltaCannotBeOmitted(){var c=declared();c.set(TaraConfig.TARA_OUTCOME_MESSAGE,"unbound receipt");assertTrue(TaraConfig.validation(c).isPresent());c=declared();c.set(TaraConfig.TARA_MINIMUM_HEALTH_DELTA,0.0);assertTrue(TaraConfig.validation(c).isPresent());}
    static MapConfigService declared(){var c=new MapConfigService();c.set(TaraConfig.TARA_USE_SOUL_WHIP,true);c.set(TaraConfig.TARA_PRIMARY_NAME,"Declared Primary");c.set(TaraConfig.TARA_PRIMARY_ITEM,"minecraft:fishing_rod");c.set(TaraConfig.TARA_FALLBACK_NAME,"Declared Fallback");c.set(TaraConfig.TARA_FALLBACK_ITEM,"minecraft:fishing_rod");c.set(TaraConfig.TARA_BOW_NAME,"Declared Bow");c.set(TaraConfig.TARA_READY_PLATE,"Declared Ready");c.set(TaraConfig.TARA_OUTCOME_MESSAGE,"Declared {boss_uuid}");c.set(TaraConfig.TARA_EGG_OUTCOME,"EXACT_LOADED_BODY_REMOVAL");c.set(TaraConfig.TARA_WHIP_PREPARATION_TICKS,3);c.set(TaraConfig.TARA_BOW_PREPARATION_TICKS,5);c.set(TaraConfig.TARA_BOW_DRAW_TICKS,20);c.set(TaraConfig.TARA_MINIMUM_HEALTH_DELTA,1.0);c.set(TaraConfig.TARA_GROUP_BUFFER_MS,100L);c.set(TaraConfig.TARA_WHIP_RETRY_MS,1000L);c.set(TaraConfig.TARA_WHIP_TIMEOUT_MS,5000L);c.set(TaraConfig.TARA_EGG_RETRY_MS,1000L);c.set(TaraConfig.TARA_EGG_TIMEOUT_MS,5000L);c.set(TaraConfig.TARA_WHIP_MAX_USES,1);c.set(TaraConfig.TARA_BOW_MAX_USES,1);c.set(TaraConfig.TARA_NATIVE_RAY_LIMIT,5.0);return c;}
}
